package io.github.ningpp.compat;

/**
 * Replacement for System.Runtime.InteropServices.Unsafe (generated by CSharpToJava converter).
 * C# ref-return APIs are modelled with holder classes; most operations are no-op
 * pass-throughs because the ref semantics have already been lowered by the converter.
 */
public class Unsafe {

    /** Mirrors Unsafe.As&lt;T&gt;(ref T value) for int refs — pass-through. */
    public static int as(IntHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.As&lt;T&gt;(ref T value) for long refs — pass-through. */
    public static long as(LongHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.As&lt;T&gt;(ref T value) for byte refs — pass-through. */
    public static byte as(ByteHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.As&lt;T&gt;(ref T value) for char refs — pass-through. */
    public static char as(CharHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.As&lt;T&gt;(ref T value) for short refs — pass-through. */
    public static short as(ShortHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.As&lt;T&gt;(ref T value) for float refs — pass-through. */
    public static float as(FloatHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.As&lt;T&gt;(ref T value) for double refs — pass-through. */
    public static double as(DoubleHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.As&lt;T&gt;(ref T value) for boolean refs — pass-through. */
    public static boolean as(BoolHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.As&lt;TFrom, TTo&gt;(ref TFrom value) — unchecked reference cast. */
    @SuppressWarnings("unchecked")
    public static <T> T as(Object value) {
        return (T) value;
    }

    /**
     * Mirrors Unsafe.Add(ref T source, int elementOffset) — returns the referenced
     * value (the holder only carries a single value; the offset is not representable).
     */
    public static int add(IntHolder holder, int offset) {
        return holder.value;
    }

    public static long add(LongHolder holder, int offset) {
        return holder.value;
    }

    /**
     * Mirrors Unsafe.AddByteOffset(ref byte source, IntPtr byteOffset) — byte read
     * at an offset. The holder only carries the first byte, so the offset cannot
     * be honoured; the caller's sequential scan relies on the loop counter.
     */
    public static int addByteOffset(IntHolder source, long byteOffset) {
        return source.value;
    }

    /** Mirrors Unsafe.ReadUnaligned&lt;int&gt;(ref byte) — pass-through. */
    public static int readUnaligned(IntHolder holder) {
        return holder.value;
    }

    /** Mirrors Unsafe.ReadUnaligned&lt;int&gt;(ref byte) for already-lowered int values. */
    public static int readUnaligned(int value) {
        return value;
    }

    /** Mirrors Unsafe.ReadUnaligned&lt;long&gt;(ref byte) — pass-through. */
    public static long readUnaligned(LongHolder holder) {
        return holder.value;
    }

    /**
     * Mirrors Unsafe.ReadUnaligned&lt;Vector&lt;byte&gt;&gt;(ref byte) — seeds a vector
     * from the first byte value (scalar fallback; SIMD path is not accelerated).
     */
    public static Vector<Integer> readUnalignedVector(int byteValue) {
        return new Vector<>(byteValue & 0xFF);
    }

    /** Mirrors Unsafe.AsPointer(ref T value) — the pointer identity is not representable. */
    public static int asPointer(Object value) {
        return 0;
    }
}
